ALTER TABLE store_items ADD COLUMN collection_id TEXT;
CREATE TABLE IF NOT EXISTS collections ( id TEXT PRIMARY KEY, name TEXT NOT NULL, name_es TEXT, description TEXT, description_es TEXT, icon TEXT, color TEXT, price INTEGER, featured INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, starts_at INTEGER, ends_at INTEGER, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
INSERT OR IGNORE INTO collections (id, name, name_es, description, description_es, icon, color, price, featured, active, sort_order, created_at, updated_at) VALUES ('backrooms', 'Backrooms pack', 'Paquete Backrooms', 'Humming lights, damp carpet, endless yellow rooms. Five items for the Liminal Industries crowd.', 'Luces que zumban, alfombra húmeda, cuartos amarillos sin fin. Cinco objetos para la banda de Liminal Industries.', '🚪', '#c9b458', 260, 1, 1, 0, strftime('%s','now')*1000, strftime('%s','now')*1000);
